mapper.select:
SELECT DISTINCT a.BALANCE_DATE AS balanceDate, a.BOOKSET_ID AS booksetId, bokset.BOOKSET_NAME as booksetName, a.SUBJECT_NO AS subjectNo, subject.SUBJECT_NAME AS subjectName, a.O_CCY AS oCcy, a.O_AMT AS oAmt, a.B_AMT AS bAmt, a.BAL_FLAG AS balFlag, a.NUM_AMT AS numAmt FROM BOK_BALANCE a LEFT JOIN BOK_BOOKSET bokset ON a.BOOKSET_ID = bokset.BOOKSET_ID INNER JOIN BOK_SUBJECT subject ON a.SUBJECT_NO = subject.SUBJECT_NO AND bokset.BOOKSET_ID_TMPL = subject.BOOKSET_ID WHERE 1=1
AND subject.SUBJECT_LEVEL =#{subjectLevel}
AND a.BOOKSET_ID IN
#{item}
AND a.SUBJECT_NO = #{subjectNo}
AND a.BALANCE_DATE >=STR_TO_DATE(#{bookDateBegin},'%Y-%m-%d')
AND a.BALANCE_DATE <=STR_TO_DATE(#{bookDateEnd},'%Y-%m-%d')
AND a.O_CCY IN
#{ccy}
UNION ALL SELECT DISTINCT a.BALANCE_DATE AS balanceDate, a.BOOKSET_ID AS booksetId, bokset.BOOKSET_NAME as booksetName, a.SUBJECT_NO AS subjectNo, bbd.DETAIL_SUBJECT_NAME AS subjectName, a.O_CCY AS oCcy, a.O_AMT AS oAmt, a.B_AMT AS bAmt, a.BAL_FLAG AS balFlag, a.NUM_AMT AS numAmt FROM BOK_BALANCE a LEFT JOIN BOK_BOOKSET bokset ON a.BOOKSET_ID = bokset.BOOKSET_ID INNER JOIN BOK_BUSS_DETSUB bbd ON bbd.BOOKSET_ID = a.BOOKSET_ID AND bbd.DETAIL_SUBJECT_NO = a.SUBJECT_NO WHERE 1=1
AND a.BOOKSET_ID IN
#{item}
AND a.SUBJECT_NO = #{subjectNo}
AND a.BALANCE_DATE >=STR_TO_DATE(#{bookDateBegin},'%Y-%m-%d')
AND a.BALANCE_DATE <=STR_TO_DATE(#{bookDateEnd},'%Y-%m-%d')
AND a.O_CCY IN
#{ccy}
ORDER BY booksetId,subjectNo asc

select distinct SUBJECT_NO as id, SUBJECT_NAME as text FROM BOK_SUBJECT WHERE 1 = 1
AND BOOKSET_ID IN ( SELECT BOOKSET_ID_TMPL FROM BOK_BOOKSET WHERE BOOKSET_ID IN
#{item}
)
AND SUBJECT_LEVEL = #{subjectLevel}
AND (SUBJECT_NO like concat_ws('','%', #{search} , '%') OR SUBJECT_NAME like concat_ws('','%', #{search} , '%'))
UNION ALL SELECT distinct DETAIL_SUBJECT_NO as id, DETAIL_SUBJECT_NAME as text FROM BOK_BUSS_DETSUB WHERE 1 = 1
AND BOOKSET_ID IN
#{item}
AND (DETAIL_SUBJECT_NO like concat_ws('','%', #{search} , '%') OR DETAIL_SUBJECT_NAME like concat_ws('','%', #{search} , '%') )
ORDER BY id ASC

SELECT BALANCE_DATE as balanceDate, '' AS booksetId, '' as booksetName, a.SUBJECT_NO AS subjectNo, IFNULL(subject.SUBJECT_NAME,bbd.DETAIL_SUBJECT_NAME) AS subjectName, a.O_CCY AS oCcy, sum(a.O_AMT) AS oAmt, sum(a.B_AMT) AS bAmt, a.BAL_FLAG AS balFlag, sum(a.NUM_AMT) AS numAmt FROM BOK_BALANCE a LEFT JOIN BOK_BOOKSET bokset ON a.BOOKSET_ID = bokset.BOOKSET_ID LEFT JOIN BOK_SUBJECT subject ON a.SUBJECT_NO = subject.SUBJECT_NO AND bokset.BOOKSET_ID_TMPL = subject.BOOKSET_ID LEFT JOIN BOK_BUSS_DETSUB bbd ON bbd.BOOKSET_ID = a.BOOKSET_ID AND bbd.DETAIL_SUBJECT_NO = a.SUBJECT_NO WHERE 1=1
AND subject.SUBJECT_LEVEL =#{subjectLevel}
AND a.BOOKSET_ID IN
#{booksetId}
AND a.SUBJECT_NO = #{subjectNo}
AND a.BALANCE_DATE >=STR_TO_DATE(#{bookDateBegin},'%Y-%m-%d')
AND a.BALANCE_DATE <=STR_TO_DATE(#{bookDateEnd},'%Y-%m-%d')
AND a.O_CCY IN
#{ccy}
GROUP BY a.BALANCE_DATE, a.SUBJECT_NO, IFNULL(subject.SUBJECT_NAME,bbd.DETAIL_SUBJECT_NAME), a.O_CCY, a.BAL_FLAG ORDER BY a.BALANCE_DATE desc, a.SUBJECT_NO
